// Pesan MQTT: andaliman/<device>/data  {"suhu":21.3,"kelembapan":73.4}
// Hasil: baris Line Protocol untuk measurement "environment" (sama dengan yang dibaca dashboard)
const dev = String(msg.topic).split("/")[1];
if (!/^[A-Za-z0-9_-]+$/.test(dev)) { node.warn("device_id tidak valid: " + dev); return null; }

const p = msg.payload || {};
const t = Number(p.suhu);
const h = Number(p.kelembapan);
if (!Number.isFinite(t) || !Number.isFinite(h)) { node.warn("data tidak valid: " + JSON.stringify(p)); return null; }

msg.lp = `environment,device_id=${dev} suhu=${t},kelembapan=${h}`;
return msg;

// Pesan MQTT: andaliman/<device>/state {status relay, mode, safe_reason}
// Hasil: baris Line Protocol untuk measurement "actuator_state".
// Angka ditulis dengan akhiran "i" agar tipenya sama dengan data contoh dari seed-influx.mjs.
const dev = String(msg.topic).split("/")[1];
if (!/^[A-Za-z0-9_-]+$/.test(dev)) { node.warn("device_id tidak valid: " + dev); return null; }

const p = msg.payload || {};
const on = (v) => (v === 1 || v === true || v === "1" ? 1 : 0);
const mode = String(p.mode || "").toUpperCase();
if (!["AUTO", "MANUAL", "SAFE"].includes(mode)) { node.warn("mode tidak dikenal: " + p.mode); return null; }
const safeReason = ["sensor_gagal", "dipilih_pengguna"].includes(p.safe_reason) ? p.safe_reason : "";

msg.lp = `actuator_state,device_id=${dev} kompresor=${on(p.kompresor)}i,buzzer=${on(p.buzzer)}i,fan=${on(p.fan)}i,mist=${on(p.mist)}i,mode="${mode}",safe_reason="${safeReason}"`;
return msg;

// Menyiapkan permintaan HTTP ke InfluxDB 2.x (/api/v2/write).
// Pengaturan dibaca dari environment Node-RED supaya token tidak tersimpan di file alur ini.
const url = env.get("INFLUX_URL");
const org = env.get("INFLUX_ORG");
const bucket = env.get("INFLUX_BUCKET");
const token = env.get("INFLUX_TOKEN");
if (!url || !org || !bucket || !token) {
  node.error("INFLUX_URL, INFLUX_ORG, INFLUX_BUCKET, INFLUX_TOKEN belum diatur di environment Node-RED", msg);
  return null;
}

msg.url = url.replace(/\/$/, "") + "/api/v2/write?org=" + encodeURIComponent(org) +
          "&bucket=" + encodeURIComponent(bucket) + "&precision=s";
msg.method = "POST";
msg.headers = { "Authorization": "Token " + token, "Content-Type": "text/plain; charset=utf-8" };
msg.payload = msg.lp;
return msg;

// Pesan MQTT: andaliman/<device>/wifi
//   {"connected":1,"ssid":"Rumah","rssi":-55,"ip":"192.168.1.50","hasil":"ok","target":"Rumah","id":"ab12cd34"}
// Hasil: measurement "wifi_state". `hasil`, `target`, `id` = hasil percobaan ganti Wi-Fi terakhir dari dashboard.
const dev = String(msg.topic).split("/")[1];
if (!/^[A-Za-z0-9_-]+$/.test(dev)) { node.warn("device_id tidak valid: " + dev); return null; }

const esc = (s) => String(s == null ? "" : s).replace(/[\u0000-\u001f]/g, " ").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
const p = msg.payload || {};
const bulat = (v) => (Number.isFinite(Number(v)) ? Math.trunc(Number(v)) : 0);
const hasil = ["ok", "gagal_wifi", "gagal_broker"].includes(p.hasil) ? p.hasil : "";
const conn = p.connected === 1 || p.connected === true ? 1 : 0;

// Angka ditulis dengan akhiran "i" (integer); teks di dalam tanda kutip dengan karakter khusus di-escape.
msg.lp = `wifi_state,device_id=${dev} connected=${conn}i,rssi=${bulat(p.rssi)}i,ssid="${esc(p.ssid)}",ip="${esc(p.ip)}",hasil="${hasil}",target="${esc(p.target)}",id="${esc(p.id)}"`;
return msg;

// Pesan MQTT: andaliman/<device>/wifi/scan
//   {"id":"ab12cd34","networks":[{"s":"Rumah","r":-50,"x":1}, ...]}
// Hasil: measurement "wifi_scan". Daftar jaringan disimpan sebagai satu teks JSON (dibaca dashboard).
const dev = String(msg.topic).split("/")[1];
if (!/^[A-Za-z0-9_-]+$/.test(dev)) { node.warn("device_id tidak valid: " + dev); return null; }

const esc = (s) => String(s == null ? "" : s).replace(/[\u0000-\u001f]/g, " ").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
const p = msg.payload || {};
if (!Array.isArray(p.networks)) { node.warn("daftar jaringan tidak valid"); return null; }
const daftar = p.networks.slice(0, 20)
  .filter((n) => n && typeof n.s === "string" && n.s.length > 0)
  .map((n) => ({ s: n.s.slice(0, 32), r: Math.trunc(Number(n.r)) || 0, x: n.x ? 1 : 0 }));

msg.lp = `wifi_scan,device_id=${dev} networks="${esc(JSON.stringify(daftar))}",id="${esc(p.id)}"`;
return msg;
